  const node=playback.createBufferSource();node.buffer=buffer;node.connect(playback.destination);
  next=Math.max(next,playback.currentTime+.02);node.start(next);next+=buffer.duration;nodes.push(node);
  node.onended=()=>{nodes=nodes.filter(n=>n!==node);};
