  capture=new AudioContext({sampleRate:16000});
  if(capture.sampleRate!==16000)throw Error('16kHz capture unavailable; implement a tested resampler');
  const worklet=`class Capture extends AudioWorkletProcessor {process(inputs){if(inputs[0]?.[0])this.port.postMessage(inputs[0][0].slice());return true;}}registerProcessor('capture',Capture);`;
  const url=URL.createObjectURL(new Blob([worklet],{type:'text/javascript'}));
  try{await capture.audioWorklet.addModule(url);}finally{URL.revokeObjectURL(url);}
  processor=new AudioWorkletNode(capture,'capture');
  processor.port.onmessage=message=>{
   if(!ws||ws.readyState!==1)return;
   if(ws.bufferedAmount>64000){eventLog('Uplink overload; microphone stopped');stopMic();return;}
   const samples=message.data,bytes=new ArrayBuffer(samples.length*2),view=new DataView(bytes);
   for(let i=0;i<samples.length;i++)view.setInt16(i*2,Math.round(Math.max(-1,Math.min(1,samples[i]))*32767),true);
   ws.send(bytes);
  };
  const input=capture.createMediaStreamSource(stream);muted=capture.createGain();muted.gain.value=0;
  input.connect(processor);processor.connect(muted);muted.connect(capture.destination);el('mic').disabled=true;
 }catch(error){stopMic();el('status').textContent=error.message;}
};
el('send').onclick=()=>{if(ws?.readyState===1)ws.send(JSON.stringify({type:'text',text:el('text').value}));};
el('stop').onclick=()=>{stopMic();if(ws?.readyState===1)ws.send(JSON.stringify({type:'audio_end'}));clearPlayback();};
